import{b as i,P as r,I as e,g as o,j as t,e as l,af as n,k as d,l as g,S as c}from"./chunks/framework.CrSplIeq.js";const f=JSON.parse('{"title":"Ringkasan Proyek","description":"","frontmatter":{},"headers":[],"relativePath":"overview.md","filePath":"overview.md"}'),m={name:"overview.md"};function p(h,a,u,k,b,y){const s=r("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="ringkasan-proyek" tabindex="-1">Ringkasan Proyek <a class="header-anchor" href="#ringkasan-proyek" aria-label="Permalink to &quot;Ringkasan Proyek&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Related Code</span></span>\n<span class="line"><span>- `lib/main.dart`</span></span>\n<span class="line"><span>- `lib/screens/chat_screen.dart`</span></span>\n<span class="line"><span>- `pubspec.yaml`</span></span></code></pre></div><p>SmartAI Chat adalah aplikasi chat UI berbasis Flutter yang menampilkan asisten AI bernama <strong>Natsya</strong>. Proyek ini dibangun menggunakan <strong>Forui</strong> sebagai library UI (bukan Material Design murni) dan <strong>Riverpod 3</strong> untuk state management. Fokus utama adalah pada pengalaman UI percakapan yang modern dengan message bubbles bergaya chat, sidebar sesi, dan toggle tema terang/gelap.</p><p>Saat ini data chat masih bersifat <strong>mock</strong> (belum terhubung ke backend AI atau API manapun).</p><h2 id="tech-stack-radar" tabindex="-1">Tech Stack Radar <a class="header-anchor" href="#tech-stack-radar" aria-label="Permalink to &quot;Tech Stack Radar&quot;">​</a></h2><ul><li><strong>Flutter 3.41+</strong> — Framework UI cross-platform</li><li><strong>Dart 3.11+</strong> — Bahasa pemrograman</li><li><strong>Riverpod ^3.3.1</strong> — State management berbasis <code>Notifier</code></li><li><strong>Forui ^0.21.3</strong> — UI component library dengan tema violet</li><li><strong>flutter_test</strong> — Unit &amp; widget testing</li><li><strong>flutter_lints</strong> — Static analysis</li></ul><h2 id="system-context-diagram" tabindex="-1">System Context Diagram <a class="header-anchor" href="#system-context-diagram" aria-label="Permalink to &quot;System Context Diagram&quot;">​</a></h2>',7)),(e(),l(c,null,{default:n(()=>[g(s,{id:"mermaid-48",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20user%5BUser%5D%0A%20%20%20%20app%5BSmartAI%20Chat%20App%5D%0A%20%20%20%20mock%5BMock%20Data%20Layer%5D%0A%0A%20%20%20%20user%20--%3E%7Cinteraksi%20UI%7C%20app%0A%20%20%20%20app%20--%3E%7Cbaca%20data%7C%20mock%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>Proyek ini adalah aplikasi standalone yang berjalan sepenuhnya di sisi klien. Belum ada backend atau API eksternal.</p><h2 id="architecture-highlights" tabindex="-1">Architecture Highlights <a class="header-anchor" href="#architecture-highlights" aria-label="Permalink to &quot;Architecture Highlights&quot;">​</a></h2><ol><li><strong>State Management Terpusat</strong> — Menggunakan Riverpod <code>NotifierProvider</code> untuk chat messages, sidebar toggle, dan theme mode. Setiap state memiliki notifier sendiri yang independen.</li><li><strong>Forui Sebagai Design System</strong> — Menggantikan Material widgets standar dengan Forui (<code>FScaffold</code>, <code>FHeader</code>, <code>FTextField</code>, <code>FTheme</code>) untuk tampilan yang lebih modern dan konsisten dengan tema violet.</li><li><strong>Scroll Behavior Cerdas</strong> — Chat screen memiliki auto-scroll ke pesan terbaru hanya jika user sedang di bagian bawah, memberi kontrol penuh pada user saat men-scroll ke atas.</li></ol><h2 id="key-risks-tech-debt" tabindex="-1">Key Risks / Tech Debt <a class="header-anchor" href="#key-risks-tech-debt" aria-label="Permalink to &quot;Key Risks / Tech Debt&quot;">​</a></h2><ol><li><strong>Belum Ada Backend</strong> — Semua data masih mock (<code>lib/mock/</code>). Tidak ada integrasi API, database, atau AI asli. Ini adalah pure UI prototype.</li><li><strong>Belum Ada Routing</strong> — Menggunakan <code>MaterialApp</code> dengan <code>home:</code> langsung. Tidak ada GoRouter atau Navigator 2.0. Perlu routing formal saat halaman bertambah.</li><li><strong>Manajemen Keyboard</strong> — Input FTextField tidak menangani keyboard show/hide secara eksplisit, yang bisa menyebabkan layout issue di beberapa platform.</li></ol>',5))])}const A=i(m,[["render",p]]);export{f as __pageData,A as default};
